WITH recent_web_events AS (SELECT * FROM web_events WHERE event_type IN ('add_to_cart', 'page_view') OR event_time >= '2024-10-01'), web_events_stats AS (SELECT event_type, CASE WHEN duration_sec >= 411 THEN 'high' WHEN duration_sec >= 137 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, ROUND((100 * SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_add_to_cart, SUM(CASE WHEN event_type = 'search' THEN duration_sec ELSE 0 END) AS search_duration_sec FROM recent_web_events GROUP BY event_type, CASE WHEN duration_sec >= 411 THEN 'high' WHEN duration_sec >= 137 THEN 'mid' ELSE 'low' END) SELECT event_type, duration_sec_bucket, pct_add_to_cart, search_duration_sec FROM web_events_stats WHERE search_duration_sec >= 68
